const CURRENCIES = ["NGN", "USD", "GBP"] as const;
type Currency = (typeof CURRENCIES)[number];

type Balances = { [C in Currency]: number };
type Rates = { [C in Currency]: number };

function totalInNaira(balances: Balances, rates: Rates): number {
  let total = 0;
  for (const currency of CURRENCIES) total += (balances[currency] / 100) * rates[currency];
  return total;
}

const balances: Balances = { NGN: 4_500_000, USD: 12_000, GBP: 5_000 };
const rates: Rates = { NGN: 1, USD: 1500, GBP: 2000 };
console.log(totalInNaira(balances, rates));

