interface Product {
  readonly sku: string;
  name: string;
  priceKobo: number;
}

type Draft<T> = { -readonly [K in keyof T]+?: T[K] };
const REQUIRED: readonly (keyof Product)[] = ["sku", "name", "priceKobo"];

function finish(draft: Draft<Product>): Product | string[] {
  const missing = REQUIRED.filter((field) => draft[field] === undefined);
  if (missing.length > 0) return missing;
  const { sku, name, priceKobo } = draft;
  if (sku === undefined || name === undefined || priceKobo === undefined) return ["unreachable"];
  return { sku, name, priceKobo };
}

const draft: Draft<Product> = {};
draft.name = "Enamel mug";
console.log(finish(draft));
draft.sku = "MUG-07";
draft.priceKobo = 180_000;
console.log(finish(draft));

