type Setting = { env: string; defaultValue?: string };
type Schema = { [key: string]: Setting | Schema };

function isSetting(node: Setting | Schema): node is Setting {
  return typeof node.env === "string";
}

function envVarNames(schema: Schema): string[] {
  const names: string[] = [];
  for (const child of Object.values(schema)) {
    if (isSetting(child)) names.push(child.env);
    else names.push(...envVarNames(child));
  }
  return names;
}

const schema: Schema = {
  port: { env: "PORT", defaultValue: "3000" },
  paystack: { secretKey: { env: "PAYSTACK_SECRET_KEY" }, webhook: { secret: { env: "PAYSTACK_WEBHOOK_SECRET" } } },
