type DeepReadonly<T> = T extends (...args: any[]) => any ? T : { readonly [K in keyof T]: DeepReadonly<T[K]> };

function deepFreeze<T>(value: T): DeepReadonly<T> {
  if (typeof value === "object" && value !== null) {
    for (const child of Object.values(value)) deepFreeze(child);
    Object.freeze(value);
  }
  return value as DeepReadonly<T>;
}

const settings = deepFreeze({ mail: { from: "shop@example.com" }, zones: ["lagos", "abuja"] });
console.log(Object.isFrozen(settings), Object.isFrozen(settings.mail), Object.isFrozen(settings.zones));
